<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;class Lease extends Model{protected $keyType='string';public $incrementing=false;protected $fillable=['id','organization_id','tenant_id','internal_number','ejar_number','start_date','end_date','annual_rent','total_value','currency','frequency','status','version'];public function tenant():BelongsTo{return $this->belongsTo(Tenant::class);}public function installments():HasMany{return $this->hasMany(LeaseInstallment::class);}}
